package com.churn.service;
import com.churn.dto.CustomerRequest; import com.churn.entity.Customer; import com.churn.repository.CustomerRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CustomerService { private final CustomerRepository repo; public CustomerService(CustomerRepository repo){this.repo=repo;}
 public Customer create(CustomerRequest r){Customer c=new Customer(); update(c,r); return repo.save(c);} public List<Customer> all(){return repo.findAll();} public Customer get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Customer not found: "+id));}
 private void update(Customer c,CustomerRequest r){c.setGender(r.gender());c.setSeniorCitizen(r.seniorCitizen());c.setPartner(r.partner());c.setDependents(r.dependents());c.setTenure(r.tenure());c.setPhoneService(r.phoneService());c.setMultipleLines(r.multipleLines());c.setInternetService(r.internetService());c.setOnlineSecurity(r.onlineSecurity());c.setOnlineBackup(r.onlineBackup());c.setDeviceProtection(r.deviceProtection());c.setTechSupport(r.techSupport());c.setStreamingTV(r.streamingTV());c.setStreamingMovies(r.streamingMovies());c.setContract(r.contract());c.setPaperlessBilling(r.paperlessBilling());c.setPaymentMethod(r.paymentMethod());c.setMonthlyCharges(r.monthlyCharges());c.setTotalCharges(r.totalCharges());}}
